            submitTest(g1, "t1", "PASS", "insp-3", 422);
        } else {
            // 召回先提交：拆分被拦截 422，子批停留 RELEASED 但不可用，无新子批
            assertEquals(422, split);
            assertEquals("RELEASED", currentStatus(child));
